#include "module_controls.h"
#include <assert.h>
#include <stdio.h>
#include <string.h>
typedef struct {long toggle,level;char mode[64];int fail;} fake;
static int read_value(void *ctx,const char *id,long *n,char *s,size_t cap){fake *f=ctx;if(f->fail)return -1;if(!strcmp(id,"ftp-enabled"))*n=f->toggle;else if(!strcmp(id,"brightness"))*n=f->level;else if(!strcmp(id,"stream-mode")){*n=0;snprintf(s,cap,"%s",f->mode);}return 0;}
static int write_value(void *ctx,const char *id,long n,const char *s){fake *f=ctx;if(f->fail)return -1;if(!strcmp(id,"ftp-enabled"))f->toggle=n;else if(!strcmp(id,"brightness"))f->level=n;else if(!strcmp(id,"stream-mode"))snprintf(f->mode,sizeof(f->mode),"%s",s?s:"");return 0;}
int main(void){rtp_module_control_catalogue c;rtp_control_option options[2]={{"mtp","MTP"},{"mass","Mass Storage"}};rtp_control_descriptor d={0};rtp_control_backend b={read_value,write_value};fake f={1,50,"mtp",0};long n=0;char s[64]={0};rtp_module_controls_init(&c);d.id="ftp-enabled";d.title="FTP Server";d.description="Enable or disable the FTP service.";d.module_id="connectivity";d.kind=RTP_CONTROL_TOGGLE;assert(rtp_module_control_register(&c,&d)==RTP_CONTROL_OK);assert(rtp_module_control_register(&c,&d)==RTP_CONTROL_DUPLICATE);d.id="brightness";d.title="Brightness";d.kind=RTP_CONTROL_SLIDER;d.minimum=0;d.maximum=100;d.step=5;assert(rtp_module_control_register(&c,&d)==RTP_CONTROL_OK);d.id="stream-mode";d.title="USB Mode";d.kind=RTP_CONTROL_SELECT;d.minimum=d.maximum=d.step=0;d.options=options;d.option_count=2;assert(rtp_module_control_register(&c,&d)==RTP_CONTROL_OK);assert(rtp_module_control_read(&c,"ftp-enabled",&b,&f,&n,s,sizeof(s))==RTP_CONTROL_OK&&n==1);assert(rtp_module_control_write(&c,"ftp-enabled",&b,&f,0,NULL)==RTP_CONTROL_OK&&f.toggle==0);assert(rtp_module_control_write(&c,"brightness",&b,&f,53,NULL)==RTP_CONTROL_INVALID_VALUE);assert(rtp_module_control_write(&c,"brightness",&b,&f,55,NULL)==RTP_CONTROL_OK&&f.level==55);assert(rtp_module_control_read(&c,"stream-mode",&b,&f,&n,s,sizeof(s))==RTP_CONTROL_OK&&!strcmp(s,"mtp"));assert(rtp_module_control_write(&c,"stream-mode",&b,&f,0,"unknown")==RTP_CONTROL_INVALID_VALUE);d.id="locked";d.title="Locked";d.kind=RTP_CONTROL_TOGGLE;d.options=NULL;d.option_count=0;d.read_only=1;assert(rtp_module_control_register(&c,&d)==RTP_CONTROL_OK);assert(rtp_module_control_write(&c,"locked",&b,&f,1,NULL)==RTP_CONTROL_READ_ONLY);f.fail=1;assert(rtp_module_control_read(&c,"ftp-enabled",&b,&f,&n,s,sizeof(s))==RTP_CONTROL_BACKEND_ERROR);puts("Module control contract tests passed.");return 0;}
